CREATE TABLE wb_media(id text PRIMARY KEY,project_id text NOT NULL REFERENCES wb_projects(id) ON DELETE CASCADE,chapter_id text NOT NULL DEFAULT '',revision_id text NOT NULL DEFAULT '',kind text NOT NULL,status text NOT NULL,input jsonb NOT NULL,content bytea,mime text NOT NULL DEFAULT '',error text NOT NULL DEFAULT '',provider_request_id text NOT NULL DEFAULT '',usage jsonb NOT NULL DEFAULT '{}',cost_status text NOT NULL DEFAULT 'Unknown',started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wb_media_queue ON wb_media(status,created_at);
